	SUPER_FISHING(_1DOSE2FISHERSPOTION, _2DOSE2FISHERSPOTION, _3DOSE2FISHERSPOTION, _4DOSE2FISHERSPOTION),
	SUPER_HUNTER(_1DOSE2HUNTING, _2DOSE2HUNTING, _3DOSE2HUNTING, _4DOSE2HUNTING),
