package com.activitycounter.models;

import java.util.HashMap;
import java.util.Map;

public enum SpellBook
{
	REGULAR, ANCIENT, LUNAR, ARCEEUS;

	private static final Map<Integer, SpellBook> STORAGE_ID_MAP = new HashMap<>();

	static {
		for (SpellBook spellBook : values()) {
			STORAGE_ID_MAP.put(spellBook.ordinal(), spellBook);
		}
	}

	/**
	 * Returns the Spellbook associated with the given id. Ids correspond to varbit values used by the client
	 */
	public static SpellBook getById(int id) {
		return STORAGE_ID_MAP.get(id);
	}
}

